#!/usr/bin/env python3
"""Apply all bug fixes to parse.py - version 5 (clean R9)"""

with open('/tmp/writable_ws/parse_orig.py', 'r') as f:
    content = f.read()

# R7: Replace int_convert function with class-based version
old_int_convert = '''def int_convert(base):
    \'\'\'Convert a string to an integer.

    The string may start with a sign.

    It may be of a base other than 10.

    If may start with a base indicator, 0#nnnn, which we assume should
    override the specified base.

    It may also have other non-numeric characters that we can ignore.
    \'\'\'
    CHARS = \'0123456789abcdefghijklmnopqrstuvwxyz\'

    def f(string, match, base=base):
        if string[0] == \'-\':
            sign = -1
        else:
            sign = 1

        if string[0] == \'0\' and len(string) > 2:
            if string[1] in \'bB\':
                base = 2
            elif string[1] in \'oO\':
                base = 8
            elif string[1] in \'xX\':
                base = 16
            else:
                # just go with the base specifed
                pass

        chars = CHARS[:base]
        string = re.sub(\'[^%s]\' % chars, \'\', string.lower())
        return sign * int(string, base)
    return f'''

new_int_convert = '''class IntConverter:
    """Convert a string to an integer using a specified or auto-detected base."""
    CHARS = \'0123456789abcdefghijklmnopqrstuvwxyz\'

    def __init__(self, base):
        self.base = base

    def __call__(self, string, match):
        if string[0] == \'-\':
            sign = -1
        else:
            sign = 1

        base = self.base
        if string[0] == \'0\' and len(string) > 2:
            if string[1] in \'bB\':
                base = 2
            elif string[1] in \'oO\':
                base = 8
            elif string[1] in \'xX\':
                base = 16

        chars = self.CHARS[:base]
        string = re.sub(\'[^%s]\' % chars, \'\', string.lower())
        return sign * int(string, base)


def int_convert(base):
    return IntConverter(base)'''

content = content.replace(old_int_convert, new_int_convert)

# Add FloatConverter, DecimalConverter, CustomTypeConverter before percentage function
converter_classes = '''class FloatConverter:
    """Convert a string to a float."""
    def __call__(self, s, m):
        return float(s)


class DecimalConverter:
    """Convert a string to a Decimal."""
    def __call__(self, s, m):
        return Decimal(s)


class CustomTypeConverter:
    """Wrapper for a custom type converter function."""
    def __init__(self, func):
        self.func = func

    def __call__(self, string, match):
        return self.func(string)


'''

content = content.replace('def percentage(string, match):\n', converter_classes + 'def percentage(string, match):\n')

# R7: Replace lambda for float conversion (type 'f')
content = content.replace(
    "self._type_conversions[group] = lambda s, m: float(s)",
    "self._type_conversions[group] = FloatConverter()"
)

# R7: Replace lambda for Decimal conversion (type 'F')  
content = content.replace(
    "self._type_conversions[group] = lambda s, m: Decimal(s)",
    "self._type_conversions[group] = DecimalConverter()"
)

# R7: Replace custom type converter inner function with class
content = content.replace(
    '''            def f(string, m):
                return type_converter(string)
            self._type_conversions[group] = f''',
    '''            self._type_conversions[group] = CustomTypeConverter(type_converter)'''
)

# R8: Fix findall to use the correct parser p
content = content.replace(
    "return Parser(format, extra_types=extra_types).findall(string, pos, endpos, evaluate_result=evaluate_result)",
    "return p.findall(string, pos, endpos, evaluate_result=evaluate_result)"
)

# R10: Add slice support to Result.__getitem__
old_getitem = '''    def __getitem__(self, item):
        if isinstance(item, int):
            return self.fixed[item]
        return self.named[item]'''

new_getitem = '''    def __getitem__(self, item):
        if isinstance(item, slice):
            return Result(self.fixed[item], dict(self.named), dict(self.spans))
        if isinstance(item, int):
            return self.fixed[item]
        return self.named[item]'''

content = content.replace(old_getitem, new_getitem)

# R9: Modify _search_re property to handle alignment differently for search
# For left (<) and center (^) aligned fields, stop at whitespace instead of consuming fill chars
old_search_re = '''    @property
    def _search_re(self):
        if self.__search_re is None:
            try:
                self.__search_re = re.compile(self._expression, self._re_flags)'''

new_search_re = '''    @property
    def _search_re(self):
        if self.__search_re is None:
            try:
                # For search mode, align < and ^ should stop at whitespace
                # Replace patterns like (.+?)\\ * or (?P<name>.+?)\\ * with 
                # ([^ ]+) or (?P<name>[^ ]+) respectively
                expr = self._expression
                # Pattern matches: (optional_prefix)(capture_group_pattern)(space_star)(rest)
                # We want to replace (.+?) * with [^ ]+
                import re as _re_mod
                # Match anonymous group (.+?) followed by space*
                expr = _re_mod.sub(r'\\((\\.\\+\\?)\\s+\\*\\)', r'([^ ]+)', expr)
                # Match named group (?P<name>.+?) followed by space*
                expr = _re_mod.sub(r'\\(\\?P<\\w+>\\(\\.\\+\\?)\\s+\\*\\)', 
                                  r'(\\?P<\\w+>[^ ]+)', expr)
                self.__search_re = re.compile(expr, self._re_flags)'''

content = content.replace(old_search_re, new_search_re)

# Write the modified file
